export function parseCommitTrustScoreInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCommitTrustScoreInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 15) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      trustScore: getNextAccount(),
      automationPayer: getNextAccount(),
      magicFeeVault: getNextAccount(),
      trustScoreDelegationRecord: getNextAccount(),
      automationPayerDelegationRecord: getNextAccount(),
      sessionToken: getNextAccount(),
      sessionSigner: getNextAccount(),
      campaign: getNextAccount(),
      fraudFlag: getNextAccount(),
      fraudFlagEvent: getNextAccount(),
      systemProgram: getNextAccount(),
      aidtraceProgram: getNextAccount(),
      magicProgram: getNextAccount(),
      magicContext: getNextAccount(),
    },
    data: getCommitTrustScoreInstructionDataDecoder().decode(instruction.data),
  };
}
